    "id": "entity-name-removal-001",
    "category": "field_removed",
    "old_schema": "syntax = \"proto3\";\n\npackage simulation.v1;\n\nmessage Entity {\n  string entity_id = 1;\n  string name = 2;\n}\n",
    "new_schema": "syntax = \"proto3\";\n\npackage simulation.v1;\n\nmessage Entity {\n  string entity_id = 1;\n  reserved 2;\n  reserved \"name\";\n}\n",
    "schema_path": "proto/v1/entity.proto"
  },
